package com.cinenest.rooms.internal;
import com.cinenest.identity.ScopedAuthorization;import com.nimbusds.jose.util.JSONObjectUtils;import java.nio.charset.StandardCharsets;import java.security.*;import java.util.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
@Service @Transactional
class BannerService {
 final BannerRepository store;final BannerPolicy policy;final BannerAssets assets;final ScopedAuthorization authorization;
 BannerService(BannerRepository store,BannerPolicy policy,BannerAssets assets,ScopedAuthorization authorization){this.store=store;this.policy=policy;this.assets=assets;this.authorization=authorization;}
 void require(UUID a,UUID v,String action){policy.require();if(!authorization.member(a,v,true)||!authorization.permits(a,v,"content.banner."+action,true))throw new RoomFailure(403,"Banner access denied");}
 Object catalogue(UUID a,UUID v){require(a,v,"read");store.audit(a,v,null,"READ","ALLOW",0,0);return BannerAssets.ALL;}
 Object list(UUID a,UUID v){require(a,v,"read");store.audit(a,v,null,"READ","ALLOW",0,0);return store.list(v).stream().map(b->detail(b,store.revision(b.id(),b.draft()))).toList();}
 Object read(UUID a,UUID v,UUID id,boolean history){require(a,v,"read");var b=store.banner(v,id,false);store.audit(a,v,id,"READ","ALLOW",b.version(),b.version());return history?store.history(id).stream().map(r->detail(b,r)).toList():detail(b,store.revision(id,b.draft()));}
 Map<String,Object> detail(BannerRepository.Banner b,BannerRepository.Revision r){var d=new LinkedHashMap<String,Object>();d.put("bannerId",b.id());d.put("venueId",b.venue());d.put("resourceRevision",b.version());d.put("contentRevision",r.number());d.put("publishedRevision",b.published());d.put("content",r.content());d.put("reviewHash",r.hash());d.put("image",checked(r));d.put("mode","LOCAL_SYNTHETIC_ONLY");d.put("status",status(b));return d;}
 BannerAssets.Asset checked(BannerRepository.Revision r){var image=assets.resolve(r.content().assetId());if(!image.sha256().equals(r.assetHash()))throw new RoomFailure(503,"Illustration integrity unavailable");return image;}
 String status(BannerRepository.Banner b){if(b.published()==null)return b.version()==b.draft()?"DRAFT":"UNPUBLISHED";if(!store.venueVisible(b.venue()))return "VENUE_UNAVAILABLE";var c=store.revision(b.id(),b.published()).content();var now=store.now();return now.isBefore(c.startsAt())?"SCHEDULED":now.isBefore(c.endsAt())?"LIVE":"EXPIRED";}
 Object publicBanners(UUID venue){if(!policy.enabled())return List.of();return store.live(venue).stream().map(b->{var r=store.revision(b.id(),b.published());var c=r.content();return Map.of("bannerId",b.id(),"venueId",b.venue(),"revision",r.number(),"title",c.title(),"description",c.description(),"altText",c.altText(),"image",checked(r),"linkTarget",c.linkTarget(),"visibleForMillis",Math.max(0,Math.min(15000,java.time.Duration.between(store.now(),c.endsAt()).toMillis())));}).toList();}
 static UUID uuid(Object s){try{return UUID.fromString((String)s);}catch(RuntimeException e){throw new RoomFailure(400,"Invalid command identity");}}
 @SuppressWarnings("unchecked") Object mutate(UUID actor,UUID venue,UUID id,String action,Map<String,Object> input){
  require(actor,venue,Set.of("PUBLISH","UNPUBLISH").contains(action)?"publish":"edit");if(action.equals("PUBLISH"))require(actor,venue,"read");
  Set<String> keys=switch(action){case "CREATE"->Set.of("commandId","content");case "EDIT"->Set.of("commandId","expectedRevision","content");case "PUBLISH"->Set.of("commandId","expectedRevision","contentRevision","reviewHash");default->Set.of("commandId","expectedRevision");};if(!keys.equals(input.keySet()))throw new RoomFailure(400,"Invalid command fields");
  UUID command=uuid(input.get("commandId"));var canonical=new TreeMap<String,Object>(input);if(input.get("content") instanceof Map<?,?> c)canonical.put("content",new TreeMap<>((Map<String,Object>)c));canonical.put("action",action);canonical.put("venue",venue.toString());canonical.put("target",id==null?"NEW":id.toString());String hash=digest(JSONObjectUtils.toJSONString(canonical));store.commandLock(actor,command);var prior=store.command(actor,command);
  if(prior.isPresent()){var p=prior.get();if(!p.hash().equals(hash)||!p.venue().equals(venue)||!p.action().equals(action))throw new RoomFailure(409,"Command content changed");return Map.of("bannerId",p.banner(),"resultRevision",p.result(),"replayed",true);}
  BannerRepository.Banner old=action.equals("CREATE")?null:store.banner(venue,id,true);if(old!=null&&old.version()!=BannerPolicy.number(input,"expectedRevision"))throw new RoomFailure(409,"Banner changed; reload and compare");long before=old==null?0:old.version();var next=new BannerRepository.Banner(old==null?UUID.randomUUID():id,venue,before+1,old==null?1:old.draft(),old==null?null:old.published());
  if(action.equals("CREATE")||action.equals("EDIT")){if(!(input.get("content") instanceof Map<?,?>))throw new RoomFailure(400,"Invalid banner content");var c=BannerPolicy.content((Map<String,Object>)input.get("content"));var image=assets.resolve(c.assetId());next=new BannerRepository.Banner(next.id(),venue,next.version(),old==null?1:old.draft()+1,next.published());var revision=new BannerRepository.Revision(next.draft(),c,actor,digest(JSONObjectUtils.toJSONString(Map.of("content",new TreeMap<>((Map<String,Object>)input.get("content")),"venue",venue.toString(),"banner",next.id().toString(),"revision",next.draft(),"author",actor.toString()))),image.sha256());if(old==null)store.create(next);else store.update(next);store.revision(next,revision);
  }else if(action.equals("PUBLISH")){var reviewed=store.revision(id,old.draft());if(reviewed.author().equals(actor))throw new RoomFailure(403,"Independent publisher required");checked(reviewed);if(BannerPolicy.number(input,"contentRevision")!=old.draft()||!reviewed.hash().equals(input.get("reviewHash")))throw new RoomFailure(409,"Preview changed; review again");next=new BannerRepository.Banner(id,venue,next.version(),old.draft(),old.draft());store.update(next);
  }else{next=new BannerRepository.Banner(id,venue,next.version(),old.draft(),null);store.update(next);}
  UUID audit=store.audit(actor,venue,next.id(),action,"ALLOW",before,next.version());store.command(actor,command,venue,next.id(),action,hash,next.version(),audit);return Map.of("bannerId",next.id(),"resultRevision",next.version(),"replayed",false);
 }
 static String digest(String text){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(text.getBytes(StandardCharsets.UTF_8)));}catch(NoSuchAlgorithmException e){throw new IllegalStateException("SHA-256 unavailable",e);}}
}
